#!/usr/bin/env node
/**
 * Emits the server's copy of the public namespace (D2, plan 2.7):
 * functions/_public_collections.json, from security/collections.json's
 * `public` entries. Cloud Functions deploy only functions/, so the
 * publicPublish/publicUnpublish callables and the re-sync triggers
 * (functions/public_namespace.js) read this generated file, never the table.
 *
 * Per public collection: its source collection, the source's apps (the
 * entitlement scope publish is checked against), the projection, the
 * publish tier, the publish condition and required fields, the file fields,
 * the size limit, and `projectionVersion`: a hash of everything that shapes
 * a published doc, so a doc projected under an older table is recognisable
 * (scripts/firestore_admin/migrations/2026-11-05_publish_public_backfill.js
 * re-projects those).
 *
 * Run through security/generate.js (which writes it, and checks it with
 * --check).
 */
'use strict';

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const JSON_PATH = path.join(ROOT, 'functions', '_public_collections.json');
const DEFAULT_MAX_BYTES = 65536;

/** What shapes a published doc, hashed: the server re-projects a doc whose version differs. */
function projectionVersion(cfg) {
  const shape = { projection: cfg.projection, fileFields: cfg.fileFields };
  return crypto.createHash('sha256').update(JSON.stringify(shape)).digest('hex').slice(0, 12);
}

/** { publicCollection: config } for every kind "public" entry, sorted. */
function publicCollections(table) {
  const out = {};
  for (const name of Object.keys(table.collections).sort()) {
    const entry = table.collections[name];
    if (entry.kind !== 'public') continue;
    const source = table.collections[entry.source] || {};
    const cfg = {
      source: entry.source,
      apps: source.apps || [],
      projection: entry.projection,
      publishTier: entry.publishTier || 'edit',
      publishWhen: entry.publishWhen || {},
      requiredFields: entry.requiredFields || [],
      fileFields: entry.fileFields || [],
      maxBytes: entry.maxBytes || DEFAULT_MAX_BYTES,
    };
    cfg.projectionVersion = projectionVersion(cfg);
    out[name] = cfg;
  }
  return out;
}

function renderJson(table) {
  return `${JSON.stringify({
    comment: 'GENERATED by security/generate.js (security/generate_public.js) from security/collections.json. Do not edit: change the table and run `node security/generate.js`.',
    collections: publicCollections(table),
  }, null, 2)}\n`;
}

/** Writes (or with --check, verifies) the server's config. */
function main(table, argv = []) {
  const next = renderJson(table);
  const current = fs.existsSync(JSON_PATH) ? fs.readFileSync(JSON_PATH, 'utf8') : null;
  if (argv.includes('--check')) {
    if (current !== next) {
      console.error(`${path.relative(ROOT, JSON_PATH)} is out of date with security/collections.json. Run \`node security/generate.js\` and commit the result.`);
      process.exitCode = 1;
    }
    return;
  }
  if (current !== next) {
    fs.writeFileSync(JSON_PATH, next);
    console.log(`${path.relative(ROOT, JSON_PATH)} regenerated.`);
  }
}

module.exports = { JSON_PATH, DEFAULT_MAX_BYTES, projectionVersion, publicCollections, renderJson, main };
